import { CATALOG, type CatalogEntry } from "./catalog.generated";
import type { IntegrationCategory, IntegrationConnection, IntegrationDefinition } from "./types";

/**
 * Integration catalogue.
 *
 * Two layers:
 *  - `CATALOG` (generated): every service Navio can reach, with its real brand
 *    mark. Regenerated by `scripts/sync-integrations.mjs`, never hand-edited.
 *  - `FIRST_CLASS` (curated): the services with an adapter in this build, which
 *    declare the credentials they need and the tools they expose.
 *
 * Honesty rule: Navio never pretends. A service is "Connected" only when real
 * credentials for it exist in the server environment. Everything else reads
 * "Available", and Navio is told in its system prompt which tools actually
 * exist, so it cannot claim to have used one.
 */

export { CATALOG };
export type { CatalogEntry };

