/** Every service, with the curated detail merged in where it exists. */
export interface CatalogService {
  slug: string;
  name: string;
  category: string;
  logo: string | null;
  description?: string;
  /** True when an adapter exists in this build. */
  implemented: boolean;
  requiredEnv: string[];
  /** The mark is too dark to read unaided on Navio's surfaces. */
  dark: boolean;
}

const FIRST_CLASS_BY_ID = new Map(FIRST_CLASS.map((definition) => [definition.id, definition]));

export function allServices(): CatalogService[] {
  const generated = CATALOG.map((entry) => ({
    slug: entry.slug,
    name: entry.name,
    category: entry.category,
    dark: entry.dark,
  }));

  const extras = EXTRA_SERVICES.filter((extra) => !BY_SLUG.has(extra.slug)).map((extra) => ({
    ...extra,
    dark: false,
  }));

  return [...generated, ...extras].map((entry) => {
    const curated = FIRST_CLASS_BY_ID.get(entry.slug);
    return {
      slug: entry.slug,
      name: curated?.name ?? entry.name,
      category: curated?.category ?? entry.category,
      logo: logoPath(entry.slug),
      description: curated?.description,
      implemented: Boolean(curated?.implemented),
      requiredEnv: curated?.requiredEnv ?? [],
      dark: entry.dark,
    };
  }).sort((a, b) => a.name.localeCompare(b.name));
}

/** Services shown first: the ones with adapters, then the household names. */
export const FEATURED_SLUGS = [
  "github", "slack", "gmail", "notion", "linear", "google-calendar", "stripe", "jira",
  "salesforce", "hubspot", "figma", "airtable", "asana", "shopify", "zoom", "discord",
  "google-drive", "trello", "supabase", "intercom", "zendesk", "clickup", "dropbox", "twilio",
];

export function featuredServices(): CatalogService[] {
  const byId = new Map(allServices().map((service) => [service.slug, service]));
  return FEATURED_SLUGS.map((slug) => byId.get(slug)).filter((service): service is CatalogService =>
    Boolean(service),
  );
}

export function integrationById(id: string): IntegrationDefinition | undefined {
  return FIRST_CLASS.find((integration) => integration.id === id);
}

/**
 * Resolve the true status of an integration from the server environment.
 * Never called from the browser — the result is passed down as plain data.
 */
export function resolveStatus(definition: {
  implemented: boolean;
  requiredEnv: string[];
}): IntegrationConnection["status"] {
  if (!definition.implemented) return "available";
  const configured = definition.requiredEnv.every((name) => {
    const value = process.env[name];
    return typeof value === "string" && value.trim().length > 0;
  });
  return configured ? "connected" : "not_configured";
}

export const STATUS_LABEL: Record<IntegrationConnection["status"], string> = {
  connected: "Connected",
  available: "Available",
  not_configured: "Not connected",
  error: "Needs attention",
};

/** Kept for the workspace store, which seeds one connection row per adapter. */
export const INTEGRATIONS = FIRST_CLASS;

export function byCategory(): Array<{ category: IntegrationCategory; items: IntegrationDefinition[] }> {
  return CATEGORY_ORDER.filter((category) =>
    FIRST_CLASS.some((integration) => integration.category === category),
  ).map((category) => ({
    category: category as IntegrationCategory,
    items: FIRST_CLASS.filter((integration) => integration.category === category),
  }));
}
